\label{thm:innovation_recursion}
    Assume that $R_t \subseteq S_t$ for $t \in [T]$. Under Assumptions
    \ref{assump:nested-states}, \ref{assump:memorylessness},
    \ref{assump:no-confounding-b}, \ref{assump:dynamic-consistency},
    and \ref{assump:positivity}, we have the following recursion for
    all $t \in [T+1]$:  

    \begin{equation}
      \label{eq:innovation_recursion}
      \begin{split}
        &\mathbb{P}(\underline{N}_{t}(\underline{g}_{t-1}) = \underline{n}_{t}, \underline{A}_{t}(\underline{g}_{t-1}) = \underline{a}_{t} \mid A_{t-1}(\underline{g}_{t-1}) = a_{t-1}, S_{t-1} = s_{t-1}) \\
        = &\mathbb{P}(\underline{N}_{t+1}(\underline{g}_t) = \underline{n}_{t+1}, \underline{A}_{t+1}(\underline{g}_t) = \underline{a}_{t+1} \mid A_{t}(\underline{g}_t) = a_t, S_t = s_t) g_t(a_t \mid s_t)\mathbb{P}(n_t \mid a_{t-1}, s_{t-1}),
      \end{split}
    \end{equation}
    in which we use the convention that $A_0$, $S_0$,
    $N_{T+2}$, $S_{T+1}$, $A_{T+1}$, $A_{T+2}$ are empty.

